// Stage 8 Reading Lab questions: ITEMS[mission id] = items in the format of js/rlab.js, on the Stage 8 unit topics
// (Unit 2 Design and architecture, Unit 3 Our society, Unit 4 Advertising). Each unit has 6 per mission: 2 Core, 2 Stretch,
// 2 Challenge. Option 0 is right (shuffled on screen); key and traps are words in the passage. Ids start r8- so Stage 9
// results never mix. Don't rename ids once students have used them.

const one = t => [["", t]];
const paraOpts = (right, whys) => [{ t: `Paragraph ${right}` }, ...Object.entries(whys).map(([k, why]) => ({ t: `Paragraph ${k}`, why }))];
const pick = (set, right, whys) => [{ t: `${right}: ${set.names[right]}` }, ...Object.entries(whys).map(([k, why]) => ({ t: `${k}: ${set.names[k]}`, why }))];
const gapStem = "Choose the word for the gap.";

/* ---------------- passages used by more than one question ---------------- */
const TOWER = [["A", "The Lotus Tower opened in 2015. At 180 metres, it is the tallest building in the city."],
  ["B", "A glass lift takes visitors up to the viewing floor on the 50th floor in just forty seconds."],
  ["C", "Tickets cost 150,000 dong for adults. Children under six go free, and there is a discount for students."],
  ["D", "The architect wanted the tower to look like a lotus flower opening in the morning, so the top floors are wider than the bottom."]];
const DESERT = [["A", "In the desert towns of Iran, traditional houses have thick walls made of mud bricks. The walls take many hours to warm up, so the rooms stay cool in the day."],
  ["B", "On the roofs stand tall wind towers. They catch the breeze high above the street and send it down into the rooms below."],
  ["C", "In the middle of many houses there is a courtyard with a small pool. As the water evaporates, it cools the air around it."],
  ["D", "Today, some architects are copying these ideas in new buildings, because they keep people comfortable without using any electricity."]];
const HONEY = [["A", "Engineers have admired the honeycomb for centuries. Bees build it from wax, and it is both light and very strong."],
  ["B", "The secret is the hexagon. Six-sided cells fit together with no gaps, so bees use the smallest amount of wax to store the most honey."],
  ["C", "Architects have borrowed the idea. One stadium in China has a roof made of hexagonal panels, which let in light while keeping the structure light."],
  ["D", "However, not every shape from nature works for people. A shape that suits a tiny insect may be too weak, or far too expensive, at the size of a building."]];
const CENTRE = [["A", "Green Lane Community Centre is open from 7 a.m. to 9 p.m., Monday to Saturday. It is closed on Sundays."],
  ["B", "We run classes in cooking, first aid and computer skills. Most classes are free for residents over sixty."],
  ["C", "Our café is run by volunteers from the neighbourhood, and all the money it makes goes to the centre."],
  ["D", "Would you like to help? Fill in a form at the front desk, or email us. You must be at least fourteen."]];
const STREET = [["A", "Five years ago, Hang Bac Street was full of motorbikes and cars. The pavements were narrow, and parents were afraid to let children walk to school."],
  ["B", "Then the city closed the street to traffic at weekends. At first, many shop owners complained that their customers would disappear."],
  ["C", "In fact, the opposite happened. Families came to walk, eat and shop, and sales went up by almost a third."],
  ["D", "Now the city is planning to make three more streets car-free, and residents can vote on which ones."]];
const WEALTH = [["A", "Many people believe that the richer a country is, the happier its people are. Measures such as GDP per capita are often used to compare countries."],
  ["B", "Researchers, however, have found that money only makes a big difference up to a point. Once people have enough for food, housing and healthcare, more income adds surprisingly little happiness."],
  ["C", "Costa Rica is often given as an example. Its people earn far less than people in the USA, yet they report similar happiness and live almost as long."],
  ["D", "What seems to matter more is community spirit: having friends and family nearby, and feeling that you can trust your neighbours."]];
const SHOP = [["A", "Supermarkets are designed to make you spend. As you walk in, you smell fresh bread and see bright fruit, which puts you in a good mood."],
  ["B", "Essential items like milk and eggs are kept at the back, so you must walk down several aisles to reach them."],
  ["C", "Sweets and small snacks wait at the checkout, at the eye level of young children."],
  ["D", "Want to avoid these tricks? Write a shopping list at home, and don't go shopping when you are hungry."]];
const INFLU = [["A", "Ten years ago, most brands paid film stars to appear in their adverts. Today, many prefer influencers with a much smaller online audience."],
  ["B", "The reason is trust. Followers often see an influencer as a friend rather than a celebrity, so they are more likely to believe a recommendation."],
  ["C", "Not all influencers are honest, though. Some do not say when a post has been paid for, even though the law in many countries says they must."],
  ["D", "Experts advise young people to look for words like \"ad\" or \"sponsored\" before they believe what they see."]];
const HISTORY = [["A", "Advertising is much older than television. In ancient Rome, shop owners painted messages on walls to tell people what they sold."],
  ["B", "When printing was invented, adverts started to appear in newspapers. For the first time, the same message could reach thousands of readers."],
  ["C", "Radio and television brought sound and pictures, and slogans became famous across whole countries."],
  ["D", "Today, adverts follow us online. They are chosen for each person based on what they have searched for, which some people find useful and others find worrying."]];

/* ---------------- matching sets ---------------- */
